/* Deadlands – Mächte: Arkane Hintergründe, Harrowed, neue Mächte (Buch S. 55–77) */
(function(){
var D = window.DLD = window.DLD || {};
var RN = ["Anfänger","Fortgeschritten","Veteran","Heroisch","Legendär"];
function tal(name, r, req, b, pg){ return {n:name, s:req, pg:pg, tag:[r > 2 ? "p" : r > 0 ? "b" : "g", RN[r]], b:b}; }
function dlTal(k, extra){ /* Talente der Kategorie aus talente.js (Buch Deadlands) */
  var L = (window.SW_TALENTE || []).filter(function(t){ return t.bk === "sw_dl" && t.k === k; });
  return L.map(function(t){ return tal(t.n, t.r, (t.v || "Keine Voraussetzungen"), t.b, t.p); });
}
function stat(k){ return {k:k}; }
function kv(a){ return {cards:[{n:"Auf einen Blick", s:"Werte des Arkanen Hintergrunds", b:[], k:a}], c:1}; }
function facts(a){ return {html:'<div class="dbox"><h5>Auf einen Blick</h5><dl class="dk">' + a.map(function(x){ return "<dt>" + x[0] + "</dt><dd>" + x[1] + "</dd>"; }).join("") + "</dl></div>"}; }
function PW(rank, pp, range, dur){ return [["Rang", rank],["Machtpunkte", pp],["Reichweite", range],["Dauer", dur]]; }

D["maechte/blessed"] = {t:"Blessed", pg:55, secs:[
 {id:"werte", t:"Arkaner Hintergrund (Blessed)", pg:55, b:[
  facts([["Talent","Arkaner Hintergrund (Blessed)"],["Voraussetzungen","Anfänger, Willenskraft W6+, Glaube W4+"],["Arkane Fertigkeit","Glaube (Willenskraft)"],["Startmächte","3 (Heiliges Symbol, dazu zwei nach Wahl des Spielers)"],["Machtpunkte","15"],["Verfügbare Mächte","Arkaner Schutz, Verbannen, Barriere, Tierfreund, Blenden, Eigenschaft erhöhen/senken, Verwirrung, Abwehren, Arkanes entdecken (nicht verbergen), Aufheben, Weissagung, Elementarmanipulation, Empathie, Schutz vor Naturgewalten, Chaos, Heilung, Heiliges Symbol, Licht (nicht Dunkelheit), Schmerzlinderung, Schutz, Linderung, Wiederauferstehung, Heiligung, Trägheit/Beschleunigung, Waffe verbessern, Sprachen sprechen, Betäuben, Kriegersegen"]]),
  {p:"**Wunder:** Blessed können Talente nehmen, die den Arkanen Hintergrund (Wunder) voraussetzen."},
  {p:"**Rückschlag:** Ein Kritischer Fehlschlag bei einem Glaube-Wurf verursacht beim Blessed eine Stufe Erschöpfung und beendet alle gerade aktiven Mächte."},
  {p:"**Sündigen:** Blessed, die gegen ihre Grundüberzeugungen verstoßen (siehe Sünde, S. 56), werden von den Mächten des Guten, die ihnen ihre Kräfte verleihen, verlassen. Leichte Sünden geben dem Charakter eine Woche lang –2 auf Glaube-Würfe. Schwere Sünden rauben ihm eine Woche lang alle arkanen Kräfte. Todsünden führen dazu, dass der Charakter verlassen bleibt, bis der reuige Held eine große Aufgabe oder Sühne vollbracht hat, um seine verlorenen Kräfte zurückzuerhalten (Entscheidung des Marshals)."}
 ]},
 {id:"spielen", t:"Einen Blessed spielen", pg:55, b:[
  {p:"Blessed sind Menschen, denen von geheimnisvollen und fernen Mächten des Guten übernatürliche Fähigkeiten verliehen wurden. Manche sind Priester oder echte Geistliche, andere werden einfach wegen der Edelmut ihres Kampfes oder ihrer Seele auserwählt. Obwohl die meisten erleuchtet und von Natur aus gut sind, müssen sie es nicht sein – manchmal wählt das Licht auch gequälte Seelen, um seinen Willen auszuführen."},
  {p:"Die meisten Leute an der Grenze zollen Gott – oder Allah, oder den Geistern, oder wer auch immer den Wagen in ihrer jeweiligen Halleluja-Planwagenfahrt lenkt – Lippenbekenntnisse, hören aber nicht wirklich auf zu sündigen, bis sie ihm von Angesicht zu Angesicht begegnen. Manchmal werden Segnungen verliehen, weil die Seele unter der Oberfläche rein ist, andere Male, weil eine bestimmte Person eben zum göttlichen – wenn auch oft verborgenen – Plan des Allmächtigen passt."},
  {p:"Einige auserwählte Seelen sind edler. Sie leben die Ideale ihres Glaubens und sind Leuchtfeuer der Hoffnung für andere. Diese werden gemeinsam die „Blessed“ genannt. Nicht alle Blessed sind Prediger oder Nonnen. Der Herr wirkt wahrlich auf geheimnisvollen Wegen, und manchmal scheinen die störrischsten Kerle den göttlichen Wind zu erben, sozusagen, während der örtliche Padre nicht einmal ohne Streichholz eine Kerze anzünden kann."}
 ]},
 {id:"suende", t:"Sünde", pg:56, b:[
  {p:"Die Blessed machen ihr Leben zum Beispiel für andere und enthalten sich sündiger Wege. Die Angaben dazu, was für Christen – die häufigste Religion an der Grenze – als Sünde gilt, sind ein guter Anhaltspunkt für die Regeln anderer Konfessionen."},
  {table:{cap:"Sünden-Tabelle", cols:["Schwere","Beispiel"], rows:[["Leicht","Den Namen des Herrn missbrauchen, sich betrinken, lügen, Bedürftigen die Hilfe verweigern, fremden Besitz beneiden."],["Schwer","Diebstahl, Menschen in großer Not abweisen, die Kommunion versäumen (bei Katholiken)."],["Tod","Ehebruch, töten außer in Notwehr, Blasphemie (Verleugnung des Glaubens)."]]}},
  {h:"Erscheinungsbild"},
  {p:"Die Mächte der Blessed sind immer unaufdringlich, wenn nicht gar unwahrnehmbar – meist so sehr, dass nur die Wirkungen sichtbar sind. Die Blessed werden von den göttlichen Wesen des „Guten“ als ihre Streiter auserwählt. Ja, es gibt göttliche Wesen des Guten in Deadlands, sie müssen nur durch die Menschheit wirken, statt selbst mit dem Bösen zu kämpfen. Wir machen die kosmischen Regeln nicht, Amigo, wir erzählen dir nur davon."}
 ]},
 {id:"talente", t:"Talente der Blessed", pg:56, b:[
  {cards:[
   tal("Wahrer Gläubiger", 0, "Anfänger, Willenskraft W10+, Arkaner Hintergrund (Blessed), Glaube W6+", ["Dieser Betbruder scheint das Ohr seiner Gottheit zu haben. Er erhält einen kostenlosen Wiederholungswurf bei Glaube-Würfen."], 56),
   tal("Herde", 2, "Veteran, Arkaner Hintergrund (Blessed), Überreden W8+", ["Die größten Propheten und Prediger werden von Anhängern begleitet. Diese Männer und Frauen haben in dem Blessed auf die eine oder andere Weise Erlösung gefunden und ihr Leben seiner Sache gewidmet. Herde gibt deinem Padre fünf Anhänger, die ihm in beliebiger von dir gewählter Funktion zur Seite stehen. Sie haben die Werte von Stadtbewohnern (siehe S. 151), können aber wie alle Verbündeten Aufstiege machen (siehe Savage Worlds). Sie kommen mit nichts als der Kleidung am Leib und ein paar Dollar, können aber bewaffnet und ausgerüstet werden, wie der Blessed es für richtig hält. Gestorbene Mitglieder der Herde werden mit der Zeit ersetzt (meist durch eine „Erweckung“). Das Talent darf nicht mehr als einmal genommen werden, bis der Blessed Legendär ist. Dann darf er es so oft nehmen, wie er will (ebenso das Talent Gefolgsleute, falls er möchte)."], 56)
  ], c:2}
 ]}
]};

D["maechte/chi"] = {t:"Chi Master", pg:57, secs:[
 {id:"werte", t:"Arkaner Hintergrund (Chi Master)", pg:57, b:[
  facts([["Talent","Arkaner Hintergrund (Chi Master)"],["Voraussetzungen","Anfänger, Geschicklichkeit W6+, Willenskraft W6+, Kampfkünstler, Fokus W4+"],["Arkane Fertigkeit","Fokus (Willenskraft)"],["Startmächte","3 (Abwehren, dazu zwei nach Wahl des Spielers)"],["Machtpunkte","15"],["Verfügbare Mächte","Arkaner Schutz, Eigenschaft erhöhen/senken, Graben, Fluch, Dunkelsicht, Abwehren, Arkanes entdecken (nicht verbergen), Empathie, Schutz vor Naturgewalten, Fernsicht, Heilung, Schmerzlinderung, Schutz, Linderung, Trägheit/Beschleunigung, Waffe verbessern (Hände und Füße zählen für diese Macht als Waffen), Wandkrabbler, Kriegersegen"]]),
  {p:"**Begabt:** Chi Master können Talente nehmen, die den Arkanen Hintergrund (Begabt) voraussetzen."},
  {p:"**Rückschlag:** Ein Kritischer Fehlschlag bei einem Fokus-Wurf verursacht beim Chi Master eine Stufe Erschöpfung und beendet alle gerade aktiven Mächte."},
  {p:"**Innerer Fokus:** Chi Master lenken die Kraft der Ewigen Jagdgründe (Hunting Grounds) durch ihren Körper. Vorteilhafte Mächte haben die Reichweite Selbst (statt der angegebenen Reichweite) und können nicht auf andere gewirkt werden. Nachteilige Mächte (wie Eigenschaft senken oder Trägheit) können andere beeinflussen, haben aber die Reichweite Berührung. Unwillige Ziele müssen per Berührungsangriff erreicht werden – dann darf die Macht als Multi-Aktion auf sie gewirkt werden. Keine der beiden Reichweiten-Verringerungen gewährt den Begrenzungsbonus für Selbst oder Berührung."}
 ]},
 {id:"spielen", t:"Einen Chi Master spielen", pg:57, b:[
  {p:"**Der Becher läuft über.** Kampfkünste zu lernen erfordert jahrelanges Training. Ein Chi Master zu werden dauert noch länger und verlangt einen Lehrer, genannt Sifu. Der Mentor lehrt den Schüler, mystische Energie in ihren Körper zu lenken und damit ihre Kampfkunst zu steigern."},
  {p:"Ein Sifu kann der Leiter einer berühmten Kampfkunstschule sein oder ein wandernder Weiser, den die meisten für einen Landstreicher halten. Die meisten Schüler des Sifu „schließen“ als fähige Kampfkünstler „ab“; nur wenige lernen, ihr Chi zu meistern. Der Schlüssel für diese seltenen wenigen ist, eine tiefe spirituelle Philosophie anzunehmen, Harmonie mit der Natur und der Welt zu finden und vor allem die Fähigkeit, Kraft aus den Ewigen Jagdgründen ohne Mittler wie einen Dämon oder Naturgeist zu lenken."},
  {p:"Angehende Chi Master müssen das Talent Kampfkünstler (siehe Savage Worlds) nehmen, um den körperlichen Aspekt ihrer Ausbildung abzubilden. Das Talent Arkaner Hintergrund (Chi Master) deckt die mystische Seite ab. Die Rolle eines Chi Masters ist es, Frieden und Harmonie in die Welt zu bringen. Manchmal erfordert das ein ruhiges Wort oder ein leuchtendes Beispiel. Andere Male ist die einzige Lösung plötzliche und unerbittliche Gewalt. Selbst dann bevorzugen die meisten Chi Master nicht tödliche Angriffe, damit die Besiegten eine Lektion lernen – „Die Toten lernen nicht“, sagte einmal ein Sifu."},
  {p:"Heldenhafte Chi Master stehen ihren Gefährten bei, kämpfen für Menschenrechte und Würde und drücken sich nie vor ihrer Pflicht, wenn sie den Schrecken der Reckoning gegenüberstehen. Böse Chi Master suchen Ordnung ins Chaos zu bringen, indem sie Gleichgesinnte Kampfkünstler sammeln und jeden beseitigen, der dem im Weg steht, was auch immer sie begehren."},
  {h:"Erscheinungsbild", pg:58},
  {p:"Die Mächte von Chi Mastern werden allgemein als Teil des Kampfkunststils des Kämpfers wahrgenommen statt als „Magie“, aber wer es besser weiß, erkennt stets, dass arkane Energie im Spiel ist. Komplizierte Formen, schnelle Schläge und besondere Atemtechniken können das Chi bündeln und arkane Energie kanalisieren."}
 ]},
 {id:"talente", t:"Talente der Chi Master", pg:58, b:[
  {p:"Obwohl es keine Voraussetzung ist, sollten Chi Master ernsthaft das Talent Chi aus Savage Worlds erwägen, um ihre Fähigkeiten zu ergänzen."},
  {cards:[
   tal("Überlegenes Kung Fu", 0, "Anfänger, Willenskraft W6+, Arkaner Hintergrund (Chi Master), Kämpfen W8+", ["Durch jahrelanges konzentriertes Studium bei ihrem weisen Lehrer hat dein Held mehrere Stile oder Haltungen gemeistert, die ihre besondere Kung-Fu-Praxis ausmachen. Wähle beim ersten Nehmen dieses Talents eine der folgenden Optionen und bei jedem weiteren Mal eine weitere. Als freie Aktion zu Beginn ihres Zuges kann sie einen der gewählten Stile annehmen. Die Vorteile des Stils bleiben bestehen, bis sie zu einem anderen wechselt.","**Betrunkener Stil:** Der Kämpfer taumelt herum, als wäre er sturzbetrunken, was seine Bewegungen wegen des schwankenden Gangs schwer vorhersehbar macht. Gegner ziehen 2 von Angriffswürfen ab, um ihn zu treffen, aber seine Bewegungsweite sinkt um 2 (er darf trotzdem rennen).","**Adlerklaue:** Der Krieger hält die Hände wie Klauen und schlägt schnell und bösartig auf den Feind ein wie ein pickender Raubvogel. Das gibt seinen unbewaffneten Kämpfen-Angriffen PB 4, und sie gelten als Schwere Waffe! Diese Fähigkeit ist entscheidend für Chi Master, die es mit schwer gepanzerten Gegnern zu tun haben, etwa Dr. Hellstrommes Metallautomaten!","**Gottesanbeterin:** Ein Schüler der Gottesanbeterin hält die Hände wie Haken und wechselt in einem erschreckenden Augenblick von fesselnder Ruhe zu verblüffenden Schlägen. Einmal pro Runde ist jeder, dessen Kämpfen-Angriff gegen den Kampfkünstler fehlschlägt, Abgelenkt oder Verwundbar (nach Wahl des Kampfkünstlers). Das ist besonders wirksam in Kombination mit dem Talent Gegenangriff.","**Affe:** Der Held schüttelt seine Glieder wie ein Primat und windet und verrenkt sich auf seltsame Weise, was umstehende Feinde aus dem Konzept bringt. Der Kampfkünstler erhält +2 Parade und schlägt die Angriffe seiner Feinde rasch weg. Sie kann außerdem als einzelne Aktion einen Athletik-Test gegen alle angrenzenden Feinde machen. Jeder widersteht einzeln.","**Shuai Chao:** Diese Form betont leichte Grifftechniken, gefolgt von Würfen oder Schlägen. Einmal pro Runde darf sie, wenn ein Feind einen Kämpfen-Angriff gegen den Kampfkünstler verfehlt, als freie Aktion einen Ringkampfversuch machen (siehe Ringen im Savage-Worlds-Regelwerk).","**Tan Tui:** Der Chi Master bündelt seinen Angriff in einem kräftigen Schnelltritt – er erhöht den Schaden ihres unbewaffneten Kampfes bei einem Kämpfen-Angriff pro Runde um eine Würfelstufe. Verursacht der Angriff, dass der Feind Erschüttert oder Verwundet ist, wird er außerdem bei Erfolg W4\" zurückgeschleudert, bei einer Steigerung W4+2\". Mit einem erfolgreichen Athletik-Wurf kann sie auch aufstehen, ohne die üblichen 2\" Bewegung zu verlieren.","**Wing Chun:** Wing Chun setzt auf schnelle Blocks und Beweglichkeit gegen Angriffe, wie Bambus vor einem Sturm. Das gibt dem Krieger +1 Parade und zieht 2 von jedem Nahkampfschaden ab, den sie in diesem Stil erleidet."], 58),
   tal("Himmlisches Kung Fu", 2, "Veteran, Willenskraft W8+, Überlegenes Kung Fu, Kämpfen W10+", ["Mehr Optionen stehen einem Kampfkünstler zur Verfügung, wenn sie den mystischen und körperlichen Aspekt ihrer Kunst meistert. Ein Held mit diesem Talent erhält einen zusätzlichen Stil aus Überlegenes Kung Fu und kann zwei Stile gleichzeitig annehmen, wobei sie beide Optionen nach Belieben nutzt. Sie darf einen oder beide als freie Aktion zu Beginn ihres Zuges wechseln."], 58)
  ], c:2}
 ]}
]};

D["maechte/harrowed"] = function(){
 var HE = dlTal("Harrowed");
 HE.push(tal("Unnachgiebig", 3, "Heroisch, Harrowed", ["Deader sind ein zäher und störrischer Haufen, angetrieben von der infernalen Kraft von Dämonen. Irgendwann können manche von ihnen einen Treffer einstecken, der jeden normalen Kerl umhauen würde. Ein Deader mit diesem Talent kann eine zusätzliche Wunde erleiden, bevor er Kampfunfähig ist. Das ist mit den Talenten Zäh wie Nägel und Zäher als Nägel kumulativ, und ihre maximalen Wundabzüge bleiben auf –3 begrenzt."], 62));
 var ORD = ["Katzenaugen","Verbesserte Katzenaugen","Chill o' the Grave","Klauen","Verbesserte Klauen","Ghost","Hellfire","Unnachgiebig","Infest","Soul Eater","Spook","Stitchin’","Verbessertes Stitchin’","Übernatürliches Attribut","Wither"];
 return {t:"Harrowed", pg:59, secs:[
 {id:"werte", t:"Harrowed", pg:59, b:[
  facts([["Talent","Harrowed oder Damned"],["Voraussetzungen","Wildcard, Anfänger, Willenskraft W6+"],["Harrowed-Talente","Dämonische Kraft verschafft dem Charakter Zugang zu Harrowed-Talenten."],["Den Teufel herauslassen","Der Harrowed nutzt die Kraft seines inneren Dämons, was ihn seine Seele kosten kann. Siehe Herrschaft, S. 60."],["Untot","+2 auf Robustheit und Willenskraft-Würfe zur Erholung von Erschüttert, ignoriert zusätzlichen Schaden durch Gezielte Angriffe außer gegen den Kopf, ignoriert 1 Punkt Wundabzüge, atmet nicht, immun gegen Krankheit und Gift, verblutet nicht und wird nur durch Zerstören des Gehirns endgültig erschlagen."]])
 ]},
 {id:"erde", t:"Aus der Erde gezerrt", pg:59, b:[
  {p:"Hin und wieder, wenn die Nummer eines Cowpokes aufgerufen wird, fängt ein böser Geist aus den Ewigen Jagdgründen die scheidende Seele ein, zerrt sie schreiend zurück in ihre Leiche und stößt sie an, aus dem Grab zu kriechen – ob der Wirt es will oder nicht! Diese bösen Geister haben viele Namen, etwa Dämonen, Teufel oder Schatten, aber die Agency wählte – vielleicht fälschlich – den Begriff „Manitou“, ein altes Algonkin-Wort für Geist. Diese Kreatur – der Manitou – bringt den toten Mann oder die tote Frau nicht nur ins Unleben zurück, sondern verleiht ihnen auch langsam Kräfte. Diese Untoten heißen die Harrowed – wörtlich „aus der Erde Gezerrte“."},
  {p:"Spieler können das Talent nehmen, um einen Helden schon als Harrowed beginnen zu lassen, oder ein Legendäres Talent (Damned), um sicherzustellen, dass sie als solcher enden, aber jede Wildcard hat die Chance, sich ihren todbringenden Reihen anzuschließen, indem sie einfach getötet wird!"},
  {h:"Harrowed werden", pg:59},
  {p:"Stirbt ein Held und hat noch den Großteil eines Gehirns, mischt der Spielleiter das Aktionskartenspiel und teilt eine Karte für jeden Rang des Helden aus. Kommt ein Joker, ist der Kerl auf dem Rückweg vom Knochengarten, mit einem Dämon aus den Ewigen Jagdgründen an seiner Seite."},
  {h:"Das Unleben eines Harrowed"},
  {p:"Zu sagen, das Leben eines Harrowed habe seine Höhen und Tiefen, ist wohl die Untertreibung des Jahres. Klar, ein wandelnder Leichnam hat Vorteile – es ist schwer, etwas zu töten, das schon tot ist –, aber man muss auch den ganzen Aspekt des „wandelnden Leichnams“ bedenken."}
 ]},
 {id:"unleben", t:"Eigenheiten des Unlebens", pg:60, b:[
  {cards:[
   {n:"Todeswunden", s:"Eine Narbe, die nie ganz heilt.", pg:60, b:["Harrowed haben alle mindestens eine Narbe, die nie ganz verheilt – ihre Todeswunde. Was auch immer einen Kerl das erste Mal niederstreckt, hinterlässt ein unauslöschliches Mal. Todeswunden sind nicht so schrecklich wie beim Tod – sie „heilen“ genug, um durchzugehen, und sind keine echten Wunden –, aber sie sind immer da und immer hässlich.","Die meisten Harrowed tun ihr Bestes, diese hässlichen Narben zu verbergen. Manche Wunden sind aber leichter zu verbergen als andere. Ein Harrowed, der erwürgt wurde, trägt vielleicht Hemden mit hohem Kragen. Ein Kerl, dem irgendein widerspenstiges Vieh die Eingeweide als Strumpfband nutzte, hat es wahrscheinlich schwerer."]},
   {n:"Verwesung", s:"Blasse Haut, Geruch, Tiere spüren es.", pg:60, b:["Harrowed haben blasse, teigige Haut. Sie verwesen nicht wirklich, da ein Manitou den Körper mit übernatürlicher Energie erhält, aber sie riechen auch nicht nach Rosen. Jeder, der einem Harrowed nahe kommt, nimmt mit einem Wahrnehmungswurf den Verwesungsgeruch wahr. Etwa einen Liter Alkohol zu trinken „legt“ einen Harrowed für ein bis zwei Tage „ein“. Er riecht dann wie ein Betrunkener, aber wenigstens nicht wie ein toter Betrunkener. Tiere merken es immer. Alle Reiten- oder anderen Würfe, die die Zusammenarbeit von Tieren erfordern, erhalten –2, wenn ein Harrowed sie versucht.","Und keine Sorge um das Glück deines Helden in Liebesdingen. Harrowed-Blut fließt nicht – nirgendwo. Männer können einfach nicht … leisten, und Frauen ziehen daraus nicht mehr Lust als aus einer ärztlichen Untersuchung."]},
   {n:"Herrschaft (Dominion)", s:"Den Teufel herauslassen: +W6, aber Würfeln auf der Herrschaftstabelle.", pg:60, b:["Das Ziel des Manitous ist es, irgendwann den Wirt vollständig zu übernehmen. Er kann zwischendurch gelegentlich die Kontrolle übernehmen, aber das kostet viel Energie, wenn der Wirt sich wehrt. Gelegentlich überredet der Dämon den Harrowed, ihm die Kontrolle gegen einen Ausbruch infernaler Kraft zu überlassen. Das heißt „den Teufel herauslassen“ und addiert +W6 auf alle Eigenschafts- und Schadenswürfe für die nächsten fünf Runden! Im Gegenzug muss der Harrowed sofort auf der Herrschaftstabelle auf S. 87 würfeln (oder eine Herrschaftskarte ziehen, falls ihr welche habt – nach jeder Ziehung mischen). Der Harrowed kann den Teufel so oft herauslassen, wie sie will, aber die Boni sind nicht kumulativ, und sie muss jedes Mal würfeln (oder ziehen), wenn sie ihren Dämon loslässt.","Die anfängliche Herrschaft eines Harrowed entspricht seinem Willenskraft-Würfel beim Ableben. Sinkt die Herrschaft eines Harrowed je auf null, wird sie zum mörderischen Schurken unter Kontrolle des Marshals. Eine spätere Steigerung von Willenskraft beeinflusst die aktuelle Herrschaft nicht, erhöht aber ihr Maximum, falls sie irgendwie steigt.","Manche Ergebnisse auf der Herrschaftstabelle erlauben dem Manitou ziemlich üble Dinge. Er tut sie vielleicht sofort oder wartet auf eine günstige Gelegenheit. Dann ist das Bewusstsein des Harrowed unterdrückt und der Dämon hat das Sagen. Er kann sich wie der Harrowed verhalten, sich fortschleichen, um eine teuflische Tat zu begehen, oder niedere Sterbliche dazu bringen, einander umzubringen. Der Wirt weiß und erinnert sich an nichts, es sei denn, der Manitou erzählt es ihm hinterher!"]},
   {n:"Essen & Trinken", s:"Ein Pfund Fleisch täglich; kein Wasser nötig.", pg:60, b:["Harrowed müssen täglich ein Pfund Fleisch – frisch oder Aas – essen, um ihr Unleben zu erhalten. Wer das nicht tut, riskiert Erschöpfung durch Hunger (siehe Savage Worlds), die aber nicht zum Tod führen kann – sie brechen nur zusammen, bis jemand es schafft, frisches Fleisch in ihre vertrocknete Kehle zu stopfen. Sie brauchen überhaupt kein Wasser, was praktisch sein kann, besonders in der Weite einer südwestlichen Wüste. Deader können nicht betrunken werden – was beim erwähnten Einlegen hilft – und werden von normalen Drogen oder Gift nicht beeinflusst. Schließlich können Harrowed sich keine normalen Krankheiten holen. Übernatürliche Krankheiten und Effekte sind aber erlaubt. Die Reckoners haben manchmal einen seltsamen Sinn für Humor."]},
   {n:"Schlaf", s:"W6 Stunden Ruhe, damit der Manitou auflädt.", pg:61, b:["Obwohl ein Harrowed keinen Schlaf braucht, benötigt der Manitou alle 24 Stunden W6 Stunden Ruhe, um seine böswilligen Energien aufzuladen. Wenn es Zeit zum „Schlafen“ ist, schaltet der Manitou den Körper einfach ab. Er unterhält sich währenddessen, indem er das Bewusstsein seines Wirts ihrem schlimmsten Albtraum aussetzt oder es gelegentlich zu einem Spaziergang mitnimmt, um etwas Übles zu tun (gemäß den Ergebnissen Unfug und Mord auf der Herrschaftstabelle, S. 87). Ein Harrowed kann nicht einfach ein Aufputschmittel nehmen, um wach zu bleiben. Der Held kann versuchen zu widerstehen, muss aber jede Stunde einen Willenskraft-Wurf machen oder kippt auf der Stelle um. Der Wurf wird mit fortschreitender Zeit schwerer, wobei jeder weitere Wurf einen kumulativen Abzug von –1 bis maximal –3 erhält. Der Manitou behält ein gewisses Bewusstsein für die Umgebung, sodass ein Harrowed bei Ärger genauso wahrscheinlich aufwacht wie andere."]},
   {n:"Was zur Hölle war das?", s:"Gewöhnliche Leute sind misstrauisch.", pg:61, b:["Gewöhnliche Leute sind Harrowed gegenüber von Natur aus misstrauisch. Ihre Haltung ist im Allgemeinen Unfreundlich, und Überreden-Würfe zum Verhandeln mit ihnen erhalten –2. Das sinkt auf Feindselig und –4, wenn sie sahen, wie der Harrowed etwas wirklich Groteskes oder Schreckliches tat. Auf der positiven Seite zählt Harrowed-Sein als Voraussetzung für das Talent Bedrohlich (siehe Savage Worlds)."]},
   {n:"Unleben", s:"Widerstandsfähig; nur durch Zerstören des Gehirns zu töten.", pg:61, b:["Es dürfte nicht überraschen, dass lebende Tote ziemlich widerstandsfähig sind. Harrowed addieren +2 auf die Erholung von Erschüttert und erleiden keine Erschöpfung durch Gefahren, gegen die sie immun sind, etwa solche im Zusammenhang mit Atmen. Sie erleiden Wunden normal, ignorieren aber eine Stufe Wundabzüge. Bei Kampfunfähigkeit wird wie üblich auf Konstitution gewürfelt. Wenn sie durch etwas anderes als einen Kopfschuss „sterben“, sind sie nur für W6 Tage außer Gefecht, wonach sie mit drei Wunden aufwachen. Harrowed können nur durch Zerstören des Gehirns getötet werden (ein Gezielter Angriff auf den Kopf oder massiver Schaden, wenn der Spielleiter meint, das würde den Schädel zerstören). Ist das Gehirn Matsch, sind der Manitou und der Harrowed wirklich tot."]},
   {n:"Heilung", s:"Alle fünf Tage ein natürlicher Heilungswurf – mit Fleisch.", pg:61, b:["Harrowed, die ihre tägliche Fleischration bekommen, dürfen wie üblich alle fünf Tage einen natürlichen Heilungswurf machen. Der Deader muss sich irgendwie selbst zusammennähen (Nadel und Faden, Ballendraht usw.); er kann sogar Körperteile wieder annähen (sofern sie nicht zerfallen sind).","Die Macht Wiederauferstehung kann einen Harrowed ins Leben zurückholen. Geschieht das, wird der Dämon erschlagen und er verliert alle Harrowed-Fähigkeiten. Natürlich tut der Manitou alles, um das zu verhindern! Die bloße Existenz dieser wandelnden Leichen ist eine Beleidigung für die Naturgeister. Keine nützliche Magie indianischer Schamanen – einschließlich Heilung – wirkt auf sie, schädigende oder schadensverursachende Mächte funktionieren aber bestens."]},
   {n:"Coup zählen", s:"Die Essenz mächtiger Kreaturen aufnehmen.", pg:61, b:["Viel Übles lauert im Weird West. Die meisten dieser Kreaturen haben zumindest einen Funken übernatürlicher Energie in sich, die mächtigsten viel. Stirbt eine dieser Kreaturen, kann ein Harrowed, der näher ist als der Willenskraft-Würfel der Kreatur in Spielfeldzoll, „Coup zählen“ und ihre Essenz aufnehmen. Harrowed, die Coup zählen, erhalten ziemlich seltsame Fähigkeiten, aber manche Kräfte haben auch einen Nachteil. All das Böse in sich aufzunehmen ist keine Kleinigkeit. Jedenfalls können Harrowed nur bei den mächtigeren Kreaturen des Weird West Coup zählen. Geringere Viecher haben einfach nicht genug Mojo zum Einsammeln. Sind mehrere Harrowed in Reichweite, um Coup zu zählen, machen sie vergleichende Willenskraft-Würfe, um zu sehen, wer die Ehre erhält. Kann ein Harrowed von einer Kreatur eine Coup-Kraft erhalten, steht sie in der Beschreibung der Kreatur. Der Marshal kennt die Einzelheiten, welche Kräfte von welcher Kreatur kommen."]},
   {n:"Unreine Abscheulichkeit!", s:"Harrowed zählen als übernatürlich böse.", pg:61, b:["Das Untote ist nicht nur Blumen und Eiscreme, Hombre. Durch ihre bloße Existenz sind Harrowed Abscheulichkeiten und Beleidigungen des Lebens. Unabhängig vom Wesen des Wirts zählen Harrowed wegen des Manitous in ihnen immer als übernatürlich böse. Jeder Harrowed, der in seinem untoten Zustand verharren will, muss diesen Status vor den meisten Leuten verbergen. Gewöhnliche Leute, die die wahre Natur deines Helden entdecken, setzen sich wahrscheinlich nicht für eine lange Erklärung hin, wie all diese Seltsamkeit zustande kam. Wahrscheinlich schießen sie zuerst, hängen als Zweites, zerstückeln als Drittes, verbrennen als Viertes – und vergessen, Fragen zu stellen! Zudem wissen einige Behörden von den Harrowed und versuchen womöglich, jene zu vernichten, die sie für gefährlich halten, ob sie ein Gesetz gebrochen haben oder nicht."]}
  ], c:2}
 ]},
 {id:"talente", t:"Harrowed-Talente", pg:62, b:[
  {p:"Ein Held erhält ein Harrowed-Talent in dem Moment, da er aus dem Grab zurückkommt. Bei Aufstiegen kann der Deader statt eines normalen Talents ein neues Harrowed-Talent wählen. Manchmal kommt dein Held zurück, ohne ganz zu wissen, dass er tot ist. In diesem Fall darf der Marshal dich warten lassen, bis dein Kerl die Wahrheit erkennt, bevor du dein erstes Harrowed-Talent nimmst."},
  {cards:HE, c:3}
 ]}
 ]};
};

D["maechte/huckster"] = function(){
 var HX = [tal("Hexenschießen (Hexslinging)", 1, "Fortgeschritten, Arkaner Hintergrund (Huckster), Schießen W8+", ["John Henry „Doc“ Holliday war ein Huckster, der die Geheimnisse der „Runenmagie“ lernte, eines Vorgangs, mit dem die alten Wikinger vor langer Zeit ihre Waffen verzauberten. Er ritzte die Runen in seinen Lieblingssechsschüsser, und das „Hexenschießen“ war geboren. Einem Wink Hoyles folgend, gab Doc diese Techniken in einer Reihe von Groschenromanen an seine Freunde weiter, passend betitelt Die Abenteuer des Doc Holliday.","Hexenschützen, die Hollidays Geheimnisse lernen, erhalten die Macht Ammo Whammy (S. 75) und können ihre eigenen runenverzierten „Hexenwaffen“ herstellen. Das dauert vier Stunden pro Waffe, die meiste Zeit davon mit dem Einritzen verschiedener Runen in den Lauf. Die Waffe kann jede Feuerwaffe sein – eine Pistole ist üblich, aber nichts hindert einen Helden, eine Hexenwaffe aus einem Derringer oder sogar einer Gatling zu machen! Nach der Fertigstellung kann jeder Hexenschütze diese Waffe nutzen, um die folgenden Mächte (sofern er sie hat) auf oder mit der Hexenwaffe zu wirken, ohne einen Multi-Aktions-Abzug zu erleiden: Ammo Whammy, Abwehren, Eigenschaft erhöhen (Schießen) und Schutz. Diese Zauber haben dabei die Reichweite Selbst und können den Modifikator Zusätzliche Ziele nicht nutzen. Die Aktivierung lässt die Runen auf der Waffe schwach glühen, Funken sprühen oder Ähnliches."], 66)];
 var ex = dlTal("Arkane Hintergründe").filter(function(c){ return c.pg >= 60; });
 return {t:"Hucksters", pg:64, secs:[
 {id:"werte", t:"Arkaner Hintergrund (Huckster)", pg:64, b:[
  facts([["Talent","Arkaner Hintergrund (Huckster)"],["Voraussetzungen","Anfänger, Glücksspiel W6+, Zaubern W4+"],["Arkane Fertigkeit","Zaubern (Verstand)"],["Startmächte","3"],["Machtpunkte","10"],["Verfügbare Mächte","Ammo Whammy, Arkaner Schutz, Barriere, Tierfreund, Blenden, Geschoss, Eigenschaft erhöhen/senken, Strahl, Verwirrung, Schadensfeld, Abwehren, Arkanes entdecken/verbergen, Verkleiden, Aufheben, Weissagung, Elementarmanipulation, Empathie, Verstricken, Schutz vor Naturgewalten, Fernsicht, Furcht, Chaos, Illusion, Unberührbarkeit, Unsichtbarkeit, Licht/Dunkelheit, Schmerzlinderung, Objekt auslesen, Schutz, Marionette, Trägheit/Beschleunigung, Schlummer, Geräusch/Stille, Sprachen sprechen, Betäuben, Verbündeten beschwören, Telekinese, Teleportation, Krimskrams (Trinkets), Wandkrabbler"]]),
  {p:"**Magie:** Hucksters können Talente nehmen, die den Arkanen Hintergrund (Magie) voraussetzen."},
  {p:"**Rückschlag:** Ein Kritischer Fehlschlag bei einem Zaubern-Wurf verursacht beim Huckster eine Stufe Erschöpfung und beendet alle gerade aktiven Mächte."},
  {p:"**Pakt mit dem Teufel:** Hucksters dürfen weder Kurzschließen noch Bennys gegen Machtpunkte ausgeben (siehe Savage Worlds), können aber einen Pakt mit dem Teufel schließen, um Mächte wirken zu können – sogar solche, die sie nicht haben und die über ihrem Rang liegen! Sie können dadurch auch zusätzliche Machtpunkte oder einen Bonus auf ihre Zaubern-Würfe erhalten. Siehe Pakt mit dem Teufel."}
 ]},
 {id:"hoyle", t:"Hoyles Huckster", pg:64, b:[
  {p:"Früher, in den wirklich alten Tagen, als die Leute noch glaubten, die Erde sei flach, war Magie weit verbreiteter als heute. Aus unbekannten Gründen begann sie irgendwann gegen Ende des Dunklen Zeitalters aus der Welt zu schwinden. Bald wurde Magie zum Stoff von Mythen und Legenden. Nicht alles war vergessen. Um 1740 zog ein Mann namens Edmund Hoyle durch Europa und setzte einige der Teile wieder zusammen. Er wusste, dass er als Hexe auf dem Scheiterhaufen enden würde, wenn er das Gelernte aufschriebe, also erfand er eine Tarngeschichte für sein Tagebuch des Arkanen. Du und ich nennen es Hoyles Spielebuch (Hoyle’s Book of Games)."},
  {p:"Der Schlüssel zu Hoyles Macht war die Verständigung mit gewissen schelmischen Geistern – er nannte sie „Joker“, um die Uneingeweihten zu verwirren – und sie in geistigen Duellen zu besiegen. Er setzte einen Teil seiner Seele gegen die Macht eines Jokers, und wenn er gewann, konnte er den Joker zwingen, eine Aufgabe zu erfüllen. Hoyle verfeinerte seine geistigen Duelle schließlich, indem er sie sich als Pokerhände vorstellte. Poker war damals relativ neu und wurde schnell zu Hoyles Spiel der Wahl, wenn er seine Flüche wirkte. Die Ausgabe von Hoyles Spielebuch von 1769 enthält diese Geheimnisse in reinster Form. Ein richtiges Lesen der komplizierten Bridge-Diagramme, numerischen Codes in Kartenspiel-Beispielen und Beispielwertungen, die das Buch durchziehen, kann Geheimnisse jenseits aller Vorstellung enthüllen. Spätere Ausgaben dieses arkanen Wälzers gibt es, doch sie sind weniger vollständig; ahnungslose Herausgeber zerstörten beim Neuordnen und Neudrucken des Manuskripts oft die arkanen Formeln."},
  {p:"Doch wer die Geheimnisse von Hoyles Spielebuch kannte, konnte selten viel Macht aufbringen. Joker schienen so selten wie Hühnerzähne, besonders solche, die stark genug für mächtige Magie waren. Dann wurde die Welt 1863 plötzlich mit Geistern – auch Jokern – überflutet, und es wurde viel leichter, Hoyles Formeln zu nutzen. Diese Zauberer des Weird West nennen sich „Hucksters“, nach den Schlangenölverkäufern, die der Öffentlichkeit so erfolgreich Sand in die Augen streuen. Andere Begriffe wurden von den Indianern geborgt (und oft falsch übersetzt), die eine andere Sicht auf das Übernatürliche haben. Joker wurden zu „Manitous“, und die übernatürliche Ebene, in der sie leben, zu den „Ewigen Jagdgründen“ (Hunting Grounds). Hexen und Hexer gelten den meisten Leuten weiterhin als böse, und ein Dilettant der sogenannten „dunklen Künste“ hält seine Hobbys besser privat. Sonst riskiert er, Ehrengast einer Krawattenparty zu werden. Außerdem gibt es mehr als ein paar Geschichten von Zauberern, die von Behörden oder übereifrigen Predigern mit ein paar mystischen Kräften gejagt werden."}
 ]},
 {id:"spielen", t:"Einen Huckster spielen", pg:65, b:[
  {p:"Will ein Huckster auf Nummer sicher gehen, kann er Hexen wie üblich wirken und seine kostbaren Machtpunkte normal verbrauchen. Ist er aber in Spiellaune, kann er für mehr Macht alles riskieren. Der angehende Hexer muss zunächst lernen, mit den Manitous zu kommunizieren. Das ist leichter gesagt als getan, zumal der Huckster versucht, mehr zu tun, als die Geister anzuschreien, sie sollen ihn in Ruhe lassen (wie es die meisten ausgeglichenen Leute in derselben Lage täten). Gelingt es, lockt der Huckster den Manitou in ein Spiel des Verstandes. Dieser Wettstreit zwischen Hucksters und Manitous ist rein geistig, aber die meisten Hucksters stellen sich den Vorgang als eine Art Spiel vor. Die große Mehrheit „spielt“ Poker, einige aber Cribbage, Rommé oder Mahjong."}
 ]},
 {id:"pakt", t:"Pakt mit dem Teufel", pg:65, b:[
  {p:"Statt einen Zauber normal zu wirken, kann ein Huckster seinen Manitou direkt herausfordern. Das ist gefährlicher als das übliche Spiel des Hucksters, hat aber viel größeres Potenzial. Der Pakt mit dem Teufel ist eine Aktion, die das Wirken des Zaubers einschließt, kann aber nur einmal pro Zug versucht werden. Während das Spiel in den Ewigen Jagdgründen Minuten oder gar Stunden zu dauern scheint, vergehen in der wirklichen Welt nur ein paar Sekunden."},
  {p:"Es gibt zwei Hauptgründe, warum ein Huckster einen Pakt mit dem Teufel schließen will. Erstens kann er jeden Zauber seiner Liste Verfügbarer Mächte wirken, auch solche, die er normalerweise nicht kennt, und auch solche über seinem aktuellen Rang! Zweitens kann er mit einem guten Blatt beliebige übrige Machtpunkte auf seinen Zaubern-Wurf oder seinen persönlichen Vorrat addieren. So geht’s:"},
  {cards:[
   {n:"1. Einsatz", s:"Gib einen Benny aus.", b:["Gib einen Benny aus. Das ist der Preis, den der Manitou fürs Mitspielen verlangt, Partner!"]},
   {n:"2. Macht wählen", s:"Welche Macht, wie viele Machtpunkte?", b:["Sage dem Marshal, welche Macht dein Huckster wirken will, und zähle die benötigten Machtpunkte zusammen, einschließlich aller Machtmodifikatoren."]},
   {n:"3. Spielen", s:"Glücksspiel-Wurf, dann fünf Karten (+1 oder +2).", b:["Mache einen Glücksspiel-Wurf, dann ziehe fünf Karten plus eine zusätzliche Karte bei einem Erfolg oder zwei bei einer Steigerung (kein Mogeln bei diesem Wurf, Amigo, der Manitou sieht zu). Ein Fehlschlag bedeutet einfach keine zusätzlichen Karten. Ein Kritischer Fehlschlag bedeutet keine zusätzlichen Karten, und nachdem der Zauber abgehandelt ist, würfelt der Marshal auf der Fehlzündungstabelle! (Siehe S. 88.)"]},
   {n:"4. Pokerblatt bilden", s:"Aus den Karten das beste Blatt, dann die Tabelle.", b:["Stelle aus den gezogenen Karten das beste Pokerblatt zusammen und schlage in der Tabelle Pakt mit dem Teufel nach. Joker sind Wild Cards, die als jede andere Karte benutzt werden können, und du bekommst deinen Einsatz (Benny) zurück! Du kannst beim Pakt mit dem Teufel nur die vom Blatt gewährten Machtpunkte nutzen – nicht deinen eigenen Vorrat. Hast du nicht genug Machtpunkte erhalten, ziehe die fehlende Zahl im nächsten Schritt vom Zaubern-Wurf ab – das Spiel ist noch nicht vorbei!"]},
   {n:"5. Zauber wirken", s:"Zaubern-Wurf mit Abzügen für Rang und fehlende Punkte.", pg:66, b:["Mache nun einen Zaubern-Wurf mit –2 für jeden Rang, den die Macht über deinem aktuellen Rang liegt (falls zutreffend), und –1 für jeden Machtpunkt, der im letzten Schritt gefehlt hat. Hat das Blatt dir mehr Machtpunkte gegeben als nötig, darfst du sie auf den Zaubern-Wurf addieren, um sein Ergebnis zu erhöhen, oder sie nutzen, um deine regulären Machtpunkte für später aufzuladen – deine Wahl, aber entscheide vor dem Würfeln. Ein Kritischer Fehlschlag hat die üblichen Folgen, und der Marshal würfelt auf der Fehlzündungstabelle! (Siehe S. 88.) Ein Fehlschlag (nach Addieren übrig gebliebener Machtpunkte, falls möglich) bedeutet, dass der Zauber misslingt. Der Huckster gibt keinen Machtpunkt aus, verliert aber den Einsatz, außer wenn ein Joker verwendet wurde."]},
   {n:"6. Hex abhandeln", s:"Wirkung wie üblich.", b:["War die Macht erfolgreich, handle ihre Wirkung wie üblich ab."]}
  ], c:3},
  {table:{cap:"Pakt mit dem Teufel", cols:["Blatt","Karten","Wirkung"], rows:[["Ass hoch","Ein Ass","2 Machtpunkte"],["Paar","Zwei Karten gleichen Werts","3 Machtpunkte"],["Buben oder besser","Ein Paar Buben oder besser","4 Machtpunkte"],["Zwei Paare","Zwei Paare","5 Machtpunkte"],["Drilling","Drei Karten gleichen Werts","6 Machtpunkte"],["Straße","Fünf aufeinanderfolgende Karten","8 Machtpunkte"],["Flush","Fünf Karten derselben Farbe","10 Machtpunkte"],["Full House","Drei Karten eines Werts, zwei eines anderen","10 Machtpunkte, Dauer, Wirkung oder Schaden verdoppelt"],["Vierling","Vier Karten gleichen Werts","15 Machtpunkte, Dauer, Wirkung oder Schaden verdoppelt"],["Fünfling","Fünf Karten gleichen Werts (erfordert einen Joker)","15 Machtpunkte, Dauer, Wirkung oder Schaden verdoppelt. Der Huckster darf nachträglich beliebige verfügbare Modifikatoren zur Macht addieren (Zusätzliche Ziele, Mehr Panzerung usw.)."],["Straight Flush","Fünf aufeinanderfolgende Karten derselben Farbe","Wie Fünfling, und der Huckster erhält Überzeugung"]]}},
  {h:"Erscheinungsbild"},
  {p:"Das Wirken eines Hexes lässt eine Hand mystischer Spielkarten in der Hand des Hucksters erscheinen. Das ist für jeden, der aufpasst, ziemlich offensichtlich. Kluge Hucksters halten ein Deck echter Karten in der Hand, um die Wahrheit zu verbergen. Dieser hübsche Taschenspielertrick ist der Grund, warum die meisten Hucksters Spieler mit Kartenmisch-Gewohnheit sind, und er täuscht die meisten, die nicht genau wissen, wonach sie suchen. Die Wirkungen sind eine andere Sache. Angriffsmächte erscheinen als geworfene, vor Energie glühende Karten. Mächte wie Eigenschaft erhöhen haben keine offensichtlichen Wirkungen, aber etwas wie Chaos schon. Ein Betrachter mit aktivem Arkanes entdecken oder ähnlichen Fähigkeiten kann die arkane Energie ebenfalls sehen, wenn der Huckster einen Hex wirkt."}
 ]},
 {id:"talente", t:"Talente der Hucksters", pg:66, b:[
  {cards:HX.concat(ex), c:3}
 ]}
 ]};
};

D["maechte/scientist"] = {t:"Mad Scientists", pg:68, secs:[
 {id:"werte", t:"Arkaner Hintergrund (Mad Scientist)", pg:68, b:[
  facts([["Talent","Arkaner Hintergrund (Mad Scientist)"],["Voraussetzungen","Anfänger, Verstand W8+, Naturwissenschaften W6+, Verrückte Wissenschaft W4+"],["Arkane Fertigkeit","Verrückte Wissenschaft (Verstand)"],["Startmächte","2"],["Machtpunkte","15"],["Verfügbare Mächte","Arkaner Schutz, Barriere, Tierfreund, Flächenschlag, Blenden, Geschoss, Eigenschaft erhöhen/senken, Graben, Strahl, Verwirrung, Schadensfeld, Dunkelsicht, Abwehren, Arkanes entdecken/verbergen, Verkleiden, Aufheben, Machtpunkte entziehen, Elementarmanipulation, Empathie, Verstricken, Schutz vor Naturgewalten, Fernsicht, Furcht, Fliegen, Chaos, Heilung, Illusion, Unberührbarkeit, Unsichtbarkeit, Licht/Dunkelheit, Gedankenleere, Schmerzlinderung, Schutz, Marionette, Linderung, Schrumpfen (nicht Wachsen), Trägheit/Beschleunigung, Schlummer, Waffe verbessern, Geräusch/Stille, Sprachen sprechen, Betäuben, Telekinese, Teleportation, Wandkrabbler, Kriegersegen, Zombie"]]),
  {p:"**Verrückte Wissenschaft:** Mad Scientists können Talente nehmen, die den Arkanen Hintergrund (Verrückte Wissenschaft) voraussetzen. Sofern hier nichts anderes steht, nutzen sie die Regeln für Verrückte Wissenschaftler aus Savage Worlds, einschließlich Notbehelf (Jury Rig; das kann Ghost Rock erfordern, Entscheidung des Marshals)."},
  {p:"**Fehlfunktion:** Würfelt ein Mad Scientist bei einem Verrückte-Wissenschaft-Wurf einen Kritischen Fehlschlag, würfelt der Marshal auf der Fehlfunktionstabelle (S. 89), um zu sehen, was geschieht."}
 ]},
 {id:"spielen", t:"Einen Mad Scientist spielen", pg:68, b:[
  {p:"Pioniere an der blutenden Spitze der Neuen Wissenschaft erschaffen und fertigen jeden Tag neue Erfindungen. Manche wollen ihre Entwürfe an Hellstromme Industries, Smith & Robards oder sogar die Armee der Vereinigten Staaten verkaufen. Für die meisten ist aber die reine Erfindung ihr eigener Lohn. Die Neue Wissenschaft wäre ohne die Entdeckung von Ghost Rock nicht möglich. Ob zu Geisterstahl verhüttet, um ihre Kessel zu verstärken, oder pulverisiert als Reagenz in Chemikalien und Elixieren genutzt: Ghost Rock ist das Fundament der Technik des Weird West."},
  {p:"Die meisten Wissenschaftler glauben, Ghost Rock sei eine Form von Bauxit, und das seltsame Heulen beim Verbrennen seien nur Taschen eingeschlossenen Sauerstoffs oder anderer Verunreinigungen, die als Katalysator der Verbrennung wirken. Aber einige behaupten, Ghost Rock sei vom Teufel selbst auf die Erde gelegt worden, um Gier, Streit und Krieg unter den Menschen zu säen. Es brenne mit der Hitze der Hölle selbst und bestehe aus den Seelen der Verdammten, die man beim Verbrennen in infernaler Qual schreien höre. Sie sagen weiter, die meisten Erfindungen, die aus seinem Studium hervorgehen, seien nicht dem menschlichen Geist entsprungen, sondern Erfindern von Dämonen der Unterwelt ins Ohr geflüstert."},
  {p:"Wie auch immer die Wahrheit aussieht: Ghost Rock brennt fünfmal heißer als Kohle, und wird es anstelle von Koks bei der Stahlerzeugung genutzt, entsteht ein Metall, das leichter und stärker ist als Stahl und einen höheren Schmelzpunkt hat. Geisterstahl hat viele unglaubliche technische Fortschritte ermöglicht, darunter pferdelose Kutschen und Flugmaschinen, dank seines geringeren Gewichts und Kessel, die höhere Temperaturen aushalten, als sonst möglich wäre. Sowohl der Norden als auch der Süden nutzten im blutigen Bürgerkrieg Ghost-Rock-Waffen mit großer Wirkung. Die ruinierten Hüllen, Brandspuren und zerschmetterten Knochen der Toten sind noch von Kalifornien bis Gettysburg zu sehen."},
  {h:"Erscheinungsbild", pg:68},
  {p:"Die arkanen Kräfte von Mad Scientists nehmen die Form von Erfindungen, Gizmos und manchmal Elixieren und Tränken an. Die meisten Bürger akzeptieren ihre Erfindungen eher als Wissenschaft denn als dunkle Zauberei, sind sich aber ihrer allgemeinen Instabilität und Flüchtigkeit nur zu bewusst."},
  {p:"Mad Scientists sind sehr stolz auf ihre Erfindungen und geben ihnen extravagante Namen, um ihre Schöpfungen von anderen abzuheben, ob sie die Entwürfe verkaufen oder zur künftigen Fertigung vermarkten wollen, sobald sie „die Macken beseitigt“ haben. Die Waffe eines Erfinders ist nie bloß ein Flammenwerfer, sondern „Dr. Jergens Erstaunliches Brandgerät“ oder „Professor Plums Perniziöser Purifizierer“. Je abenteuerlicher, desto mehr Presse bekommt man offenbar – vielleicht sogar eine Einladung ins renommierte „Collegium“, eine lose Gesellschaft von Erfindern der Neuen Wissenschaft. Das solltest du mit deinen Mächten genauso machen. Gib einer Heilungsmacht statt des Namens Heilung die Begrenzung Selbst und nenne sie „Elektrisierendes Elixier gegen alle gewöhnlichen Leiden & Gebrechen“!"}
 ]},
 {id:"talente", t:"Talente der Mad Scientists", pg:69, b:[
  {cards:[
   tal("Alchemie", 1, "Fortgeschritten, Arkaner Hintergrund (Mad Scientist), Verrückte Wissenschaft W8+", ["Verrückte Wissenschaftler können je nach Erscheinungsbild ihrer Mächte bereits Tränke, Elixiere, Tinkturen und dergleichen herstellen. Sie können sie an anderen anwenden, aber nicht an andere „weitergeben“, es sei denn, sie fertigen den Gegenstand mit dem Talent Kunsthandwerker (siehe Savage Worlds). Das Trinken eines Tranks ist eine Aktion.","Das Talent Alchemie ist ein kleiner Schummel: Ein Charakter kann bis zu drei Tränke oder Elixiere herstellen und investiert in jeden einen einzelnen Machtpunkt. Die Herstellung dauert je 30 Minuten und kostet je 5 $ an verschiedenen Reagenzien und enthält immer mindestens eine Prise Ghost Rock. Es wird kein Verrückte-Wissenschaft-Wurf gemacht – die Herstellung gelingt automatisch und erzeugt eine beliebige Mischung der unten aufgeführten Tränke. Diese können frei weitergegeben werden und halten 24 Stunden. Der Wissenschaftler erhält die Machtpunkte erst zurück, wenn sie verbraucht, weggeworfen oder abgelaufen sind.","**Schlangenöl:** Der Empfänger macht einen natürlichen Heilungswurf. Ein Erfolg heilt eine Wunde, eine Steigerung zwei.","**Fokussierendes Elixier:** Addiere +1 auf die Würfe einer Eigenschaft (Wahl des Alchemisten bei der Herstellung) für drei Runden.","**Peptonic:** Der Empfänger macht einen Konstitutionswurf. Ein Erfolg entfernt eine Stufe Erschöpfung, eine Steigerung zwei."], 69),
   tal("Eisengebunden (Iron Bound)", 0, "Anfänger, Arkaner Hintergrund (Mad Scientist)", ["Jeder muss sein Handwerk irgendwo lernen. Dein Mad Scientist war Lehrling bei einem Meisterhandwerker oder arbeitete in einer Fabrik von Hellstromme Industries, einer Werkstatt von Smith & Robards oder sogar in einer der Geheimeinrichtungen der Regierung. Die Absolventen dieser schwierigen und bahnbrechenden Prüfungen in der Neuen Wissenschaft heißen „Iron Bound“. Dein Held schaffte es, seine frühere Anstellung mit etwas der Ausrüstung zu verlassen, an der er arbeitete, und hat noch ein paar Freunde, die ihm in einer Klemme ein Sonderangebot machen können.","Der Mad Scientist beginnt mit bis zu 2.000 $ an infernalen Gerätschaften oder Fahrzeugen (siehe S. 33) und senkt den Listenpreis künftig bei dieser Quelle gekaufter Geräte um 25 %. Vielleicht kann er über andere Verkaufsstellen Rabatte erhalten, indem er einige seiner Referenzen aufsagt und Erfahrungen mit anderen Erfindern teilt (Entscheidung des Marshals)."], 69),
   tal("Erzfresser (Ore Eater)", 0, "Anfänger, Arkaner Hintergrund (Mad Scientist), Verrückte Wissenschaft W6+", ["Obwohl dein Mad Scientist wahrscheinlich nicht will, dass es jemand weiß: Er hat Geschmack an Ghost Rock gefunden! Es roh zu essen ist nicht wirklich möglich – es ist schließlich Stein –, aber es lässt sich leicht pulverisieren oder zerdrücken und in seinen Lieblingswhiskey streuen oder wie Salz über sein Essen verteilen!","Das ist offensichtlich eine gefährliche Praxis, steigert aber stark die Verbindung des Verrückten Wissenschaftlers zu den Ewigen Jagdgründen. Er erhält 5 Machtpunkte, wenn dieses Talent genommen wird (zusätzlich zu allen vom Talent Machtpunkte). Der Nachteil: Wann immer er auf der Fehlfunktionstabelle würfelt und eine 13 erzielt, bekommt er statt des Ergebnisses Gremlin das Ghost-Rock-Fieber! Er kann sich das Fieber nur einmal zuziehen und muss nach den Regeln zum Ghost-Rock-Fieber auf S. 86 leben oder sterben."], 70),
   tal("Wahres Genie", 0, "Anfänger, Verstand W8+, Arkaner Hintergrund (Mad Scientist)", ["Manche sagen, die Neue Wissenschaft werde von übernatürlichen Wesen inspiriert. Die meisten Erfinder nennen das abergläubischen Unsinn, aber ein wahres Genie akzeptiert es nicht nur, sondern umarmt es! Schließlich ist es egal, woher die Idee kommt, es kommt darauf an, was man mit der Technik macht! Oder?","Immer wenn du die Wahnsinnstabelle oder die Fehlfunktionstabelle für infernale Gerätschaften nutzen musst, kannst du einen Benny ausgeben, damit der Marshal erneut würfelt, und dann das Ergebnis wählen, das dir lieber ist. Du kannst so viele Bennys ausgeben, wie du willst, bis sie alle sind oder du mit dem Ergebnis so zufrieden bist, wie es nur geht!"], 70)
  ], c:2}
 ]}
]};

D["maechte/shaman"] = {t:"Shamanen", pg:71, secs:[
 {id:"werte", t:"Arkaner Hintergrund (Shaman)", pg:71, b:[
  facts([["Talent","Arkaner Hintergrund (Shaman)"],["Voraussetzungen","Anfänger, Willenskraft W8+, Glaube W4+"],["Arkane Fertigkeit","Glaube (Willenskraft)"],["Startmächte","2"],["Machtpunkte","15"],["Verfügbare Mächte","Arkaner Schutz, Verbannen, Tierfreund, Blenden, Eigenschaft erhöhen/senken, Graben, Verwirrung, Fluch, Dunkelsicht, Abwehren, Arkanes entdecken/verbergen, Verkleiden, Aufheben, Weissagung, Machtpunkte entziehen, Elementarmanipulation, Empathie, Verstricken, Schutz vor Naturgewalten, Fernsicht, Furcht, Wachsen (nicht Schrumpfen), Chaos, Heilung, Heiliges Symbol, Unberührbarkeit, Schmerzlinderung, Schutz, Linderung, Wiederauferstehung, Heiligung, Gestaltwandeln, Trägheit/Beschleunigung, Schlummer, Waffe verbessern, Sprachen sprechen, Verbündeten beschwören, Teleportation, Wandkrabbler, Kriegersegen, Wildnisreise"]]),
  {p:"**Wunder:** Shamanen können Talente nehmen, die den Arkanen Hintergrund (Wunder) voraussetzen."},
  {p:"**Rückschlag:** Ein Kritischer Fehlschlag bei einem Glaube-Wurf verursacht beim Shamanen eine Stufe Erschöpfung und beendet alle gerade aktiven Mächte."},
  {p:"**Alte Wege:** Die hier dargestellten Shamanen beruhen auf den Sioux und Plains-Indianern, wie sie in der Welt von Deadlands beschrieben sind. Sie müssen den Eid der Alten Wege (S. 16) nicht ablegen, aber die meisten tun es. Spielleiter sind ermuntert, andere Kulturen der amerikanischen Ureinwohner zu erforschen und Talente auf bestimmte Bräuche und Glaubensvorstellungen zuzuschneiden."}
 ]},
 {id:"spielen", t:"Einen Shamanen spielen", pg:71, b:[
  {p:"„Indianer“, wie die Westler die amerikanischen Ureinwohner nennen, wissen seit Tausenden von Jahren von den Geistern. Die Kundigsten von allen sind „Medizin“-Männer oder -Frauen, gemeinsam „Shamanen“. In der modernen Zeit antworteten die Geister den Rufen der Shamanen selten. Nachdem die Reckoning 1863 begann, schienen sie plötzlich viel gesprächiger – und bereit, „dem Volk“ ihre übernatürlichen Fähigkeiten zu leihen. Mit ihrer Hilfe konnten mehrere Stämme eigene Gebiete herausschneiden und halten und der unvermeidlichen Ausbreitung der Europäer widerstehen."},
  {p:"Das ist die Verantwortung des Shamanen: im Namen seines Häuptlings und Stammes Kontakt zur Geisterwelt aufzunehmen und um Rat und Hilfe zu bitten. Die meisten sind spirituelle Anführer und Heiler ihres Volkes, manche auch Kriegsführer. Manche Shamanen werden gefürchtet, aber alle respektiert. Alle müssen ihrem Volk ein Beispiel geben und ein Leben führen, das den Geistern gefällt, die ihre Kräfte verleihen. Shamanen-Charaktere, die diese Überzeugungen nicht hochhalten, stellen fest, dass die Geister ihre Bitten selten erhören, und ein von den Geistern ignorierter Shaman ist nicht lange einer."},
  {p:"Naturgeister sind menschlichen Angelegenheiten gegenüber im Allgemeinen gleichgültig, wirken aber etwas aufgewühlt und verärgert über die Macht, die ihre bösen Gegenstücke in den letzten Jahrzehnten gewonnen haben. Vielleicht scheinen sie deshalb eher bereit, denen zu helfen, die sie anrufen, auch wenn sie weiterhin angemessene Opfer und Rituale für ihre Aufmerksamkeit verlangen."},
  {h:"Naturgeister"},
  {p:"Naturgeister wachen über ihr jeweiliges Schutzbefohlenes und nähren es. Ein Flussgeist beschützt den Fluss, Büffelgeister leiten die Herde und so weiter. Ihr Opfer und das der physischen Flora und Fauna, die sie für die Bedürfnisse der Menschheit bereitstellen, ist den Indianern heilig. Fleisch und Kleidung kommen von den Tieren, die sie vertreten. Werkzeuge von Steinen und Bäumen. Wasser und Fortbewegung von Flüssen und Bächen. Atem aus der Luft. Das sind für die Naturgeister nicht nur Ressourcen, es sind Wunder – den Menschen frei gegeben durch das große und schreckliche Opfer des Todes oder der Zerstörung ihrer Schöpfung."},
  {p:"Die Geister haben keine Zuneigung zu massenproduzierten Gegenständen, die keine Verbindung zur Natur oder einer menschlichen Seele haben. Sie verabscheuen Maschinen, die die Erde zerstören oder verschmutzen. Sie sind entsetzt über dampfbetriebene Züge und Wagen, die das Land unter sich zermalmen, große Minen, die von Dutzenden Männern betrieben werden und die Schätze der Erde für Produkte anderer verkaufen, und vor allem über den Krebs, der durch die Adern der Erde selbst läuft – Ghost Rock. Deshalb folgen viele Shamanen den „Alten Wegen“. Sie achten und huldigen den natürlichen Gaben und Opfern, die die Geister der Menschheit gewähren. So wie Hucksters magische Energie durch Manitous lenken, lenken Shamanen sie durch Naturgeister."},
  {p:"Das ist aber kein Glücksspiel. Es ist ein Prozess aus Verhandeln und Unterwerfung auf Seiten des Shamanen, um mächtige Wesen zu überzeugen, einen Teil ihrer magischen Lebensessenz auszuteilen. Shamanen, die den Alten Wegen folgen, können keine „moderne“ Technik nutzen, erhalten aber andere Segnungen der Geister (siehe Eid der Alten Wege, S. 16). Die, die neue Wege annehmen, verkehren und verhandeln weiterhin mit Naturgeistern, schließen aber nicht jede Technik aus. Viele nehmen schnelles Reisen, Waffen und alle Arten von Massenwaren an, von Kleidung bis Medizin. Sie erhalten nicht die Segnung der Naturgeister, gewinnen aber den Vorteil, moderne Geräte in das Leben ihrer Stämme und ihr eigenes zu integrieren. Die Alten Wege sind besonders stark in den Sioux-Nationen, wo Technik wegen einer „Großen Beschwörung“ (siehe S. 112), die 1881 stattfand, ohnehin behindert ist."},
  {h:"Erscheinungsbild", pg:72},
  {p:"Shamanen führen beim Ruhen oder Beten ständig verschiedene Rituale durch. Das öffnet die Kanäle zur Geisterwelt und erlaubt ihnen, Mächte später zu aktivieren, ohne die Anrufung neu zu beginnen. Singen ist ein großer Teil der Kräfte eines Shamanen, aber arkane Energie ist nicht sichtbar. Wird ein Shaman irgendwie zum Schweigen gebracht, zieht er 2 von seinen Glaube-Würfen ab."}
 ]},
 {id:"talente", t:"Talente der Shamanen", pg:72, b:[
  {cards:[
   tal("Fetisch", 0, "Anfänger, Arkaner Hintergrund (Shaman), Glaube W8+", ["Fetische sind Gegenstände, die einem Shamanen helfen, sich zu konzentrieren, wenn er die Geisterwelt kontaktieren muss. Das kann eine Strichfigur sein, die ein Lieblingstier darstellt, ein Naturbild oder eine Rassel, die hilft, die Aufmerksamkeit der fernen Naturgeister zu wecken. Ein Shaman mit einem Fetisch erhält einen kostenlosen Wiederholungswurf, wenn er einen Glaube-Wurf macht. Geht ein Fetisch verloren oder wird zerstört, kann der Shaman mit einem einstündigen Ritual Ersatz herstellen."], 72),
   tal("Gunst des Geistes", 1, "Fortgeschritten, Arkaner Hintergrund (Shaman), Glaube W8+", ["Der Shaman hat die Gunst eines bestimmten Geistes und der einzigartigen Kraft erlangt, die er ihr gewährt. Wähle bei jedem Nehmen dieses Talents eine der Mächte des Shamanen. Der Shaman kann diese Macht als Aktion ohne Multi-Aktions-Abzug wirken, sodass sie zum Beispiel Schutz anrufen und dann einen Angriff machen, um einen weiteren Segen beten oder eine andere Aktion ausführen kann. Der Shaman kann diesen Vorteil nur einmal pro Zug beanspruchen, auch wenn er Gunst des Geistes mehrmals genommen hat."], 72)
  ], c:2}
 ]}
]};

function np(n, o, rank, pp, range, dur, b, mods){
  var c = {n:n, s:rank + " · " + pp + " MP · " + range, k:PW(rank, pp, range, dur), b:b};
  if(o) c.tag = ["b", o];
  if(mods) c.b = b.concat(mods);
  return c;
}
D["maechte/neu"] = {t:"Neue Mächte", pg:75, secs:[
 {id:"einfuehrung", t:"Neue Mächte", pg:75, b:[
  {p:"Die folgenden neuen Mächte gibt es nur in Deadlands: The Weird West. Außerdem gibt es einige Änderungen an bestehenden Mächten (Verbannen, Marionette, Schmerzlinderung)."},
  {cards:[
   np("Ammo Whammy","Nur Hucksters","Fortgeschritten","4","Selbst","5",["Diese Macht kann nur von einem Huckster mit dem Talent Hexenschießen genutzt werden (siehe S. 66). Arkane Runen auf dem Lauf einer Hexenwaffe lösen verschiedene Kräfte der Kugeln darin aus und verleihen ihnen zusätzliche Durchschlagskraft und andere Überraschungen für jene, die töricht genug sind, sich mit ihm anzulegen! Solange die Macht aktiv ist, kann der Hexenschütze für jeden aus seiner Waffe abgegebenen Schuss eine der folgenden Wirkungen wählen (oder mit einer Steigerung zwei gleichzeitige Wirkungen!).","**Silberner Schmerz:** Der Schuss wirkt auf ein Wesen, als bestünde es aus seiner Schwäche. Der Hexenschütze muss die Schwäche der Kreatur kennen, und es wirkt nicht gegen bestimmte mächtige Gegner wie die Servitors. Die Manitous können mit solchem Mojo nicht mithalten.","**Kugel mit deinem Namen drauf:** Addiere +2 auf den Schießen-Wurf des Hexenschützen.","**Explosiv:** Der Schuss verursacht Schaden in einer Kleinen Schablone.","**Leuchtsignal:** Das Abfeuern dieses „Leuchtsignal“-Schusses in den Nachthimmel hebt Beleuchtungsabzüge in der unmittelbaren Umgebung für eine Minute auf. Beim Abfeuern in Gebäuden würfle einen W6: Bei 2–6 entzündet die Kugel brennbare Materialien, die sie trifft.","**Geisterkugel:** Der Schuss ist halb in dieser Welt und halb in den Ewigen Jagdgründen und hat PB 6.","**Kentucky-Windage:** Verdoppelt die Reichweite des Schusses.","**Für den Bären geladen:** Der Schuss ist eine Schwere Waffe und erhöht den Basisschaden der Waffe um eine Würfelstufe. Eine Pistole mit 2W6 verursacht mit dieser tödlichen Patrone 2W8.","**Sacramento-Überraschung:** Dieser Schuss ist von Kraft irgendeiner Art erfüllt – Feuer, Elektrizität, Kälte usw. Besonders nützlich gegen Kreaturen mit einer Umweltschwäche!"]),
   np("Verbannen (Banish)","Änderung","Veteran","3","Verstand","Sofort",["Verbannen funktioniert wie in Savage Worlds beschrieben, doch bei seiner Anwendung auf Harrowed sind einige zusätzliche Erläuterungen nötig.","Der Manitou in einem Harrowed kann mit dieser Macht nie dauerhaft verbannt oder zerstört werden – er ist an den Wirt gebunden, an Körper und Geist. Eine erfolgreiche Verbannung macht das hasserfüllte Ding aber für eine Stunde „inaktiv“. Währenddessen kann der Harrowed keines seiner Harrowed-Talente oder Den Teufel herauslassen (siehe S. 59) nutzen, behält aber die Grundfähigkeiten des Untoten. Hat der Manitou die völlige Herrschaft erlangt, kehrt das Bewusstsein des Wirts zurück, solange er inaktiv ist, wird aber wieder unterworfen, wenn der Manitou seine Kontrolle zurückgewinnt (und nicht mehr inaktiv ist)."]),
   np("Fluch (Curse)","Neu","Fortgeschritten","5","Berührung","Sofort",["Manche Praktizierende der arkanen Künste heilen ihre Verbündeten. Andere schicken ihren Feinden Krankheit. Um diesen besonders üblen Zauber zu nutzen, macht der Zaubernde einen Wurf auf seine arkane Fertigkeit, vergleichend gegen den Willenskraft-Wurf des Opfers. Bei einem Fehlschlag erleidet das Opfer sofort und bei jedem weiteren Sonnenuntergang eine Stufe Erschöpfung (weitere Anwendungen von Fluch haben keine zusätzliche Wirkung). Wird der Verfluchte Kampfunfähig, macht er jeden Tag einen Konstitutionswurf, um dem Tod zu entgehen.","**Den Fluch brechen:** Der Fluch kann vom ursprünglichen Zaubernden nach Belieben aufgehoben werden und endet automatisch, wenn sie erschlagen wird. Aufheben beseitigt einen Fluch ebenfalls, wobei jeder nur einen Versuch hat – misslingt er, übersteigt es ihre Fähigkeiten."]),
   np("Heiliges Symbol (Holy Symbol)","Neu","Anfänger","3","Selbst","5",["Böse Kreaturen tun sich schwer, einen frommen Wanderer mit wahrem Glauben – und einem Symbol seiner Gottheit als Rückhalt – anzugreifen. Einmal angerufen, muss jede übernatürlich böse Kreatur (Entscheidung des Marshals), die den Träger des Symbols direkt körperlich angreifen will, als freie Aktion einen Willenskraft-Wurf machen (die Kreatur zieht 2 ab, wenn die Blessed mit einer Steigerung wirkte). Angriffe umfassen auch Flächenangriffe, die den Träger in ihrer Schablone erfassen würden, aber nicht etwa das Umstoßen eines Regals, das auf den Träger fällt. Heiliges Symbol hat keine Wirkung auf Tests oder andere nicht schädigende Angriffe. Der Blessed muss ein tatsächliches heiliges Symbol haben, um das Wunder anzurufen. Kein heiliges Symbol, kein Heiliges Symbol. Verstanden, Amigo? Ein improvisiertes Symbol funktioniert – ein zerbrochener Fensterrahmen in Kreuzform statt eines echten Kruzifixes zum Beispiel –, aber der Blessed zieht ohne ein richtiges Symbol 2 von der Anrufung ab.","**Vampire:** Blutsauger (die aus dem Savage-Worlds-Grundregelwerk und die Nosferatu in diesem Buch) haben eine eingebaute Schwäche gegen heilige Symbole. Ein Charakter mit diesem Wunder darf beides nutzen, wie er will – die Macht (mit Machtpunkten und einem Wurf auf die arkane Fertigkeit) oder die weniger mächtigen Regeln der Schwäche (ohne Steigerungseffekt).","**Modifikatoren:** Flächeneffekt (+2/+3): Für +2 Punkte wirkt die Macht auf alle Verbündeten in einer Mittleren Schablone um den Zaubernden. Sie hindert Kreaturen nicht am Betreten des Gebiets, nur an ihren Angriffen gegen die darin. Für +3 Punkte wächst der Wirkungsbereich auf eine Große Schablone. Stark (+1): Willenskraft-Würfe der Kreatur erhalten –2 (–4 mit Steigerung)."]),
   np("Marionette (Puppet)","Änderung","—","—","—","—",["Diese Macht funktioniert wie in Savage Worlds, aber der Modifikator Geistreiter kann damit genutzt werden.","**Modifikator:** Geistreiter (+1): Der Zaubernde kann durch jedes Ziel unter dem Effekt von Marionette kommunizieren und wahrnehmen."]),
   np("Schmerzlinderung (Numb)","Neu","Anfänger","2","Willenskraft","5",["Schmerzlinderung lindert durch Verletzung verursachte Schmerzen. Bei einem Erfolg beim Wurf auf die arkane Fertigkeit ignorieren der Zaubernde und alle Verbündeten innerhalb von Willenskraft in Spielfeldzoll vom Zaubernden 1 Punkt Wund- oder Erschöpfungsabzüge, mit einer Steigerung 2. Schmerzlinderung hebt auch alle vorübergehenden Ergebnisse der Verletzungstabelle für ihre Dauer auf. Ein Charakter, der durch einen Treffer am Bein Lahm wurde, kann sich zum Beispiel normal bewegen, solange er schmerzfrei ist. Die Macht hat keine Wirkung auf dauerhafte Verletzungen."]),
   np("Heiligung (Sanctify)","Neu","Veteran","10","Besonders","Bis zum nächsten Sonnenuntergang",["Bedeutende oder wichtige Orte können dauerhaft „geheiligt“ sein – ein heiliges Gebiet, das bösen Kreaturen Schaden zufügt. Solche Orte sind das Ergebnis langer Verbindung mit einer Religion oder einem Glauben. Sie fallen meist mit einem Bauwerk von großer zeremonieller Bedeutung zusammen, etwa einer Kathedrale, können aber auch am Ort eines großen Opfers, Triumphs oder einer Tragödie entstehen. Ein Blessed kann diese Wirkungen durch anstrengendes Gebet und Hingabe vorübergehend nachbilden. Der Vorgang dauert vier Stunden am Stück Meditation und Rituale, die seiner Religion oder seinem Glauben entsprechen. Ist das geschafft, macht der Blessed seinen Glaube-Wurf. Ein Fehlschlag bedeutet schlicht vergeudete Zeit. Ein Kritischer Fehlschlag bedeutet, dass die höheren Mächte diesen Ort nicht heiligen werden und das Ritual an diesem Ort erst wieder versucht werden kann, wenn ein bedeutendes Übel besiegt ist (Entscheidung des Marshals).","Ein Erfolg bedeutet, dass ein Gebiet von etwa 27 Metern im Quadrat den Mächten der Finsternis ein Gräuel ist. Jede übernatürlich böse Kreatur (Entscheidung des Spielleiters), die versucht, den geweihten Boden zu betreten, muss zu Beginn jeder Runde (als freie Aktion) einen Willenskraft-Wurf machen oder erleidet Erschöpfung, mit –2 bei einer Steigerung beim Glaube-Wurf. Das kann zu Kampfunfähigkeit, aber nicht zum Tod führen."]),
   np("Krimskrams (Trinkets)","Neu","Anfänger","3","Verstand","5",["Krimskrams erlaubt einem Huckster, einen geringen weltlichen Gegenstand von unter einem Pfund Gewicht zu erschaffen – einen Derringer, eine Spielkarte, einen Handspiegel und so weiter. Mit einer Steigerung ist die Dauer in Minuten statt Runden (und wird bei Wunsch auch in Minuten aufrechterhalten). Erschaffene Gegenstände erscheinen meist in einer Tasche, einem Beutel oder Sack, um die Magie zu verbergen, die sie erschafft, aber das ist nicht unbedingt nötig. Nach Ablauf der Dauer verschwindet der Gegenstand aus der Wirklichkeit. Hat der Gauner erschaffene Münzen benutzt, um etwas zu kaufen, kann er Ärger bekommen, wenn der Händler herausfindet, wer ihn übers Ohr gehauen hat.","**Modifikatoren:** Vollständig (+1): Der Gegenstand ist ein vollständiger Satz oder geladen (bei Feuerwaffen), muss aber trotzdem unter die Gewichtsgrenze passen. Ein Kartenspiel hat alle 54 Karten, eine Feuerwaffe ist voll geladen und so weiter. Gewicht (+2): Der Gegenstand kann bis zu zwei Pfund wiegen."]),
   np("Wildnisreise (Wilderness Walk)","Neu","Anfänger","2","Selbst","Eine Stunde",["Wildnisreise bittet die Erdgeister, den Shamanen auf seiner Reise in die Ewigen Jagdgründe hinein und wieder heraus zu bewegen, was beschwerliche Märsche verkürzt und seine Spur verbirgt. Shamanen nutzen diese Macht, um über große Entfernungen mit ihren Verbündeten zu kommunizieren und ihre Feinde auszuspähen! Nachdem er mindestens eine Meile in der Wildnis gegangen ist (Entscheidung des Spielleiters), zählen jeweils drei Meilen als eine (es wirkt sich nicht auf die Bewegungsweite aus), und die Spuren des Shamanen sind bis auf kurze Abschnitte nicht nachzuverfolgen. Mit einer Steigerung beim Wurf auf die arkane Fertigkeit zählen jeweils fünf Meilen als eine.","**Modifikator:** Zusätzliche Ziele (+1): Die Macht kann für je 1 zusätzlichen Machtpunkt mehr als ein Ziel betreffen."])
  ], c:2},
  {box:{t:"Wovoka", b:["„Es ist eine einfache Sache, die Augen zu schließen und die Geister deine Schritte lenken zu lassen. Vertraue ihnen.“"]}}
 ]}
]};
})();
